import re
from datetime import time

def task_func(logs: list):
    error_times = []
    total_seconds = 0

    for log in logs:
        if 'error' in log.lower():
            match = re.search(r'(\d{1,2}):(\d{2}):(\d{2})', log)
            if match:
                h, m, s = map(int, match.groups())
                if 0 <= h < 24 and 0 <= m < 60 and 0 <= s < 60:
                    error_times.append(time(h, m, s))
                    total_seconds += h * 3600 + m * 60 + s

    if not error_times:
        return [], None

    avg_total_seconds = int(round(total_seconds / len(error_times)))
    avg_h = (avg_total_seconds // 3600) % 24
    avg_m = (avg_total_seconds % 3600) // 60
    avg_s = avg_total_seconds % 60

    return error_times, time(avg_h, avg_m, avg_s)
